import 'svelte/internal/disclose-version';
import * as $ from 'svelte/internal/client';

var root = $.from_html(`<p></p>`);
var root_1 = $.from_html(`<p>zero</p>`);
var root_2 = $.from_html(`<li> </li>`);
var root_3 = $.from_html(`<div class="root"><!> <ul></ul></div>`);

export default function Basic_runes($$anchor) {
	let count = 0;
	let items = ["a", "b", "c"];
	var div = root_3();
	var node = $.child(div);

	{
		var consequent = ($$anchor) => {
			var p = root();

			p.textContent = '0';
			$.append($$anchor, p);
		};

		var alternate = ($$anchor) => {
			var p_1 = root_1();

			$.append($$anchor, p_1);
		};

		$.if(node, ($$render) => {
			if (count > 0) $$render(consequent); else $$render(alternate, -1);
		});
	}

	var ul = $.sibling(node, 2);

	$.each(ul, 20, () => items, (item) => item, ($$anchor, item) => {
		var li = root_2();
		var text = $.child(li, true);

		$.reset(li);
		$.template_effect(() => $.set_text(text, item));
		$.append($$anchor, li);
	});

	$.reset(ul);
	$.reset(div);
	$.append($$anchor, div);
}
